<h1>طلب <?= e($order['order_number']??'') ?></h1><?php if(!$order): ?><div class="alert alert-danger">غير موجود</div><?php else: ?><div class="row g-3"><div class="col-lg-8"><div class="card card-body"><p><?= e($order['customer_name']) ?> — <?= e($order['customer_phone']) ?></p><p><?= e($order['customer_address']) ?>، <?= e($order['customer_city']) ?></p><table class="table"><tr><th>الصنف</th><th>الكمية</th><th>الإجمالي</th></tr><?php foreach($items as $i): ?><tr><td><?= e($i['product_name']) ?> <?= e($i['variant_name']) ?></td><td><?= $i['quantity'] ?></td><td><?= money($i['line_total']) ?></td></tr><?php endforeach; ?></table><h4><?= money($order['total']) ?></h4><a class="btn btn-outline-dark" href="<?= url('/admin/orders/'.$order['id'].'/invoice') ?>">طباعة فاتورة</a></div></div><div class="col-lg-4"><form method="post" action="<?= url('/admin/orders/update') ?>" class="card card-body"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><select name="status" class="form-select mb-3"><?php foreach(['placed','preparing','out_for_delivery','delivered','cancelled'] as $s): ?><option <?= $order['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><textarea name="admin_notes" class="form-control mb-3" placeholder="ملاحظات الإدارة"><?= e($order['admin_notes']) ?></textarea><button class="btn btn-success">حفظ الحالة</button></form></div></div><?php endif; ?>
